class MultiCmdsCommand extends Command {

	/**
	 * @param {Editor} editor
	 * @param {Array<Command>} [cmdArray=[]]
	 * @constructor
	 */
	constructor( editor, cmdArray = [] ) {

		super( editor );

		this.type = 'MultiCmdsCommand';
		this.name = editor.strings.getKey( 'command/MultiCmds' );

		this.cmdArray = cmdArray;

	}

	execute() {

		this.editor.signals.sceneGraphChanged.active = false;

		for ( let i = 0; i < this.cmdArray.length; i ++ ) {

			this.cmdArray[ i ].execute();

		}

		this.editor.signals.sceneGraphChanged.active = true;
		this.editor.signals.sceneGraphChanged.dispatch();

	}

	undo() {

		this.editor.signals.sceneGraphChanged.active = false;

		for ( let i = this.cmdArray.length - 1; i >= 0; i -- ) {

			this.cmdArray[ i ].undo();

		}

		this.editor.signals.sceneGraphChanged.active = true;
		this.editor.signals.sceneGraphChanged.dispatch();

	}

}


// ---- upstream editor/js/History.js ----
class History {

	constructor( editor ) {

		this.editor = editor;
		this.undos = [];
		this.redos = [];
		this.lastCmdTime = Date.now();
		this.idCounter = 0;

		this.historyDisabled = false;
		this.config = editor.config;

		// signals

	}
	execute( cmd, optionalName ) {

		const lastCmd = this.undos[ this.undos.length - 1 ];
		const timeDifference = Date.now() - this.lastCmdTime;

		const isUpdatableCmd = lastCmd &&
			lastCmd.updatable &&
			cmd.updatable &&
			lastCmd.object === cmd.object &&
			lastCmd.type === cmd.type &&
			lastCmd.script === cmd.script &&
			lastCmd.attributeName === cmd.attributeName;

		if ( isUpdatableCmd && timeDifference < 500 ) {

			lastCmd.update( cmd );
			cmd = lastCmd;

		} else {

			// the command is not updatable and is added as a new part of the history

			this.undos.push( cmd );
			cmd.id = ++ this.idCounter;

		}

		cmd.name = ( optionalName !== undefined ) ? optionalName : cmd.name;
		cmd.execute();
		cmd.inMemory = true;

		this.lastCmdTime = Date.now();

		// clearing all the redo-commands

		this.redos = [];
		this.editor.signals.historyChanged.dispatch( cmd );

	}

	undo() {

		if ( this.historyDisabled ) {

			alert( this.editor.strings.getKey( 'prompt/history/forbid' ) );
			return;

		}

		let cmd = undefined;

		if ( this.undos.length > 0 ) {
			cmd = this.undos.pop();
		}

		if ( cmd !== undefined ) {

			this.lastCmdTime = - Infinity;
			cmd.undo();
			this.redos.push( cmd );
			this.editor.signals.historyChanged.dispatch( cmd );

		}

		return cmd;

	}

	redo() {

		if ( this.historyDisabled ) {

			alert( this.editor.strings.getKey( 'prompt/history/forbid' ) );
			return;

		}

		let cmd = undefined;

		if ( this.redos.length > 0 ) {

			cmd = this.redos.pop();


		}

		if ( cmd !== undefined ) {

			this.lastCmdTime = - Infinity;
			cmd.execute();
			this.undos.push( cmd );
			this.editor.signals.historyChanged.dispatch( cmd );

		}

		return cmd;

	}
	clear() {

		this.undos = [];
		this.redos = [];
		this.idCounter = 0;

		this.editor.signals.historyChanged.dispatch();

	}

}


// ---- upstream editor/js/Selector.js ----
class Selector {
	constructor( editor ) {
		this.editor = editor;
		this.signals = editor.signals;
		this.selection = [];
	}
	select( object ) {

		this.setSelection( object === null ? [] : [ object ] );

	}

	setSelection( objects ) {
		const editor = this.editor;
		this.selection = objects.slice( 0, 1 );
			const object = ( objects.length === 1 ) ? objects[ 0 ] : null;
			if ( editor.selected === object ) return;

			editor.selected = object;
			editor.config.setKey( 'selected', ( object !== null ) ? object.uuid : null );

			this.signals.objectSelected.dispatch( object );
	}
	deselect() {

		this.select( null );

	}
}


