// Local adapter: engine-owned reversible operations still use the actual upstream Command.
class HostTransactionCommand extends Command {
  constructor( editor, name, operation ) {
    super( editor );
    this.type = 'HostTransactionCommand';
    this.name = name;
    this.operation = operation;
  }
  execute() { this.operation.execute(); this.editor.signals.sceneGraphChanged.dispatch(); }
  undo() { this.operation.undo(); this.editor.signals.sceneGraphChanged.dispatch(); }
}

